for line in item_lines:
    match = re.match(r"-\s*(\d+)\s+quantity of (.+)", line)
    if match:
        qty = int(match.group(1))
        item = match.group(2).strip()
        needed_items[item] = qty

# Parse commitments from replies
commitments = defaultdict(int)
for email in camping_thread["emails"][1:]:
    body = email["body"].lower()
    for item in needed_items:
        if item.lower() in body:
            # Count how many times the item is mentioned in the body
            count = body.count(item.lower())
            # If the item is plural in the checklist, allow for plural in the body
            commitments[item] += max(1, count)

# Calculate remaining items to buy
to_buy = {}
for item, qty in needed_items.items():
    committed = commitments.get(item, 0)
    remaining = qty - committed
    if remaining > 0:
        to_buy[item] = remaining

